1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM = 25;
4	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: COMPONENT_BASE_PREMIUM,
10	  moonstone: COMPONENT_BASE_PREMIUM,
11	};
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
14	const CURSED_SURCHARGE_RATE = 0.5;
15	
16	type Item = {
17	  type: string;
18	  material?: string;
19	  enchantment?: number;
20	  cursed?: boolean;
21	};
22	
23	type Step = {
24	  op: string;
25	  items: Item[];
26	};
27	
28	type Scenario = {
29	  customer: { yearsWithMHPCO: number };
30	  steps: Step[];
31	};
32	
33	type QuoteResult = {
34	  premium: number;
35	};
36	
37	type ScenarioOutput = {
38	  results: QuoteResult[];
39	};
40	
41	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
42	  sameTypeItems.length === COMPONENT_BLOCK_SIZE;
43	
44	const groupByType = (items: Item[]): Item[][] => {
45	  const groups = new Map<string, Item[]>();
46	  for (const item of items) {
47	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
48	  }
49	  return [...groups.values()];
50	};
51	
52	const basePremiumForItem = (item: Item): number =>
53	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
54	
55	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
56	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
57	  return sameTypeItems.reduce(
58	    (total, item) => total + basePremiumForItem(item),
59	    0,
60	  );
61	};
62	
63	const basePremiumForItems = (items: Item[]): number =>
64	  groupByType(items).reduce(
65	    (total, group) => total + basePremiumForGroup(group),
66	    0,
67	  );
68	
69	const cursedSurcharge = (item: Item): number =>
70	  item.cursed ? basePremiumForItem(item) * CURSED_SURCHARGE_RATE : 0;
71	
72	const totalItemSurcharges = (items: Item[]): number =>
73	  items.reduce((total, item) => total + cursedSurcharge(item), 0);
74	
75	const premiumBeforeProcessingFee = (items: Item[]): number => {
76	  const basePremium = basePremiumForItems(items);
77	  return (
78	    basePremium +
79	    totalItemSurcharges(items) +
80	    basePremium * FIRST_INSURANCE_SURCHARGE_RATE
81	  );
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
85	  results: scenario.steps.map((step) => ({
86	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
87	  })),
88	});
